# Generated by Cursor
# Edited by Cursor (number_to_ordinal for ordinals rule)
"""Number-to-words and Roman numeral helpers for rule normalizations."""

ONES = (
    "zero",
    "one",
    "two",
    "three",
    "four",
    "five",
    "six",
    "seven",
    "eight",
    "nine",
)
ORDINAL_ONES = (
    "zeroth",
    "first",
    "second",
    "third",
    "fourth",
    "fifth",
    "sixth",
    "seventh",
    "eighth",
    "ninth",
)
ORDINAL_TEENS = (
    "tenth",
    "eleventh",
    "twelfth",
    "thirteenth",
    "fourteenth",
    "fifteenth",
    "sixteenth",
    "seventeenth",
    "eighteenth",
    "nineteenth",
)
ORDINAL_TENS = (
    "",
    "",
    "twentieth",
    "thirtieth",
    "fortieth",
    "fiftieth",
    "sixtieth",
    "seventieth",
    "eightieth",
    "ninetieth",
)
TEENS = (
    "ten",
    "eleven",
    "twelve",
    "thirteen",
    "fourteen",
    "fifteen",
    "sixteen",
    "seventeen",
    "eighteen",
    "nineteen",
)
TENS = (
    "",
    "",
    "twenty",
    "thirty",
    "forty",
    "fifty",
    "sixty",
    "seventy",
    "eighty",
    "ninety",
)
ROMAN_VAL = {
    "I": 1,
    "V": 5,
    "X": 10,
}


def digit_to_word(d: int) -> str:
    """Single digit 0-9 -> word."""
    if 0 <= d <= 9:
        return ONES[d]
    return str(d)


def number_to_words(n: int) -> str:
    """Integer 0-99 or 100 -> spoken form (for years/decades/percentages)."""
    if n < 0:
        return str(n)
    if n <= 9:
        return ONES[n]
    if n < 20:
        return TEENS[n - 10]
    if n < 100:
        t, o = divmod(n, 10)
        return TENS[t] if o == 0 else f"{TENS[t]} {ONES[o]}"
    if n < 1000:
        h, r = divmod(n, 100)
        return (
            f"{ONES[h]} hundred"
            if r == 0
            else f"{ONES[h]} hundred {number_to_words(r)}"
        )
    return str(n)


def number_to_ordinal(n: int) -> str:
    """Integer 1-99 -> spoken ordinal (e.g. 37 -> thirty seventh)."""
    if n < 0:
        return str(n)
    if n <= 9:
        return ORDINAL_ONES[n]
    if n < 20:
        return ORDINAL_TEENS[n - 10]
    if n < 100:
        t, o = divmod(n, 10)
        if o == 0:
            return ORDINAL_TENS[t]
        return f"{TENS[t]} {ORDINAL_ONES[o]}"
    return str(n)


def roman_to_int(s: str) -> int | None:
    """Roman numeral II-XII -> int; single I excluded per collect_asr_artifacts."""
    if not s or s == "I":
        return None
    val = 0
    prev = 0
    for c in s:
        v = ROMAN_VAL.get(c)
        if v is None:
            return None
        val += v
        if prev < v:
            val -= 2 * prev
        prev = v
    if val < 2 or val > 12:
        return None
    return val
